export async function retryInvoice(invoiceId: string, timeoutMs = 5000) {
  const invoice = await loadInvoice(invoiceId);
  if (invoice.retryCount >= 3) return invoice;
  return scheduleInvoiceRetry(invoice, timeoutMs);
}

test('invoice retry timeout', async () => {
  await retryInvoice('inv_123', 25);
  expect(scheduleInvoiceRetry).toHaveBeenCalledWith(expect.anything(), 25);
});

export async function handlePaymentWebhook(payload: PaymentEvent, timeoutMs = 30000) {
  const verified = verifyPaymentSignature(payload);
  return dispatchPaymentWebhook(verified, { timeoutMs });
}

export type SessionClaims = { userId: string; expiresAt: number };

export function validateSessionToken(token: string): SessionClaims {
  const claims = decodeSessionToken(token);
  if (claims.expiresAt <= Date.now()) throw new Error('expired session token');
  return claims;
}

// auth middleware caller for the session token validator
export function requireAuth(request: Request) {
  const token = request.headers.get('authorization') ?? '';
  return validateSessionToken(token);
}

test('expired session token is rejected', () => {
  expect(() => validateSessionToken(expiredToken())).toThrow('expired session token');
});

export async function retryPayment(paymentId: string, retryDelayMs = 1000) {
  const payment = await loadPayment(paymentId);
  return schedulePaymentRetry(payment, retryDelayMs);
}

test('payment retry delay is preserved', async () => {
  await retryPayment('pay_123', 50);
  expect(schedulePaymentRetry).toHaveBeenCalledWith(expect.anything(), 50);
});
